select.where:
id = (select max(latest.id) from student_practice_records latest where latest.student_name=student_practice_records.student_name and DATE(latest.practice_date)=DATE(student_practice_records.practice_date))  
            and student_name like concat('%', #{studentName}, '%')
            and is_completed = #{isCompleted}
            and practice_date >= #{params.beginPracticeDate}
            and practice_date < DATE_ADD(#{params.endPracticeDate}, INTERVAL 1 DAY)

mapper.update:
update student_practice_records
student_name = #{studentName}, is_completed = #{isCompleted}, practice_date = #{practiceDate}, remark = #{remark}, created_at = #{createdAt},
where id = #{id}
